css_rules:
:root { --vh: 1vh; --default-font: "Britti Sans"; --header-font: "Feature Display"; --ref-screen-width: 1440; --site-padding-x: min(60px, calc(40 * 100vw / var(--ref-screen-width))); --site-padding-y: var(--site-padding-x); --color-white: #fbfff4; --content-width: calc(100vw - var(--site-padding-x) * 2); --content-unit: calc(var(--content-width) / var(--ref-screen-width)); --h1: max(80px, calc(var(--content-unit) * 200)); --h2: max(65px, calc(var(--content-unit) * 110)); --sub1: max(16px, calc(var(--content-unit) * 22)); --body1: max(16px, calc(var(--content-unit) * 20)); }
h2 { font-family:var(--header-font);font-weight:200;margin:0;padding:0;line-height:1 }
h2 { font-size:var(--h2) }
.sub1 { font-family:var(--header-font);font-weight:400 }
.sub1 { font-size:var(--sub1) }
.body1 { font-family:var(--default-font);font-weight:300;font-size:var(--body1) }
@font-face { font-family:Feature Display;font-weight:200;font-style:normal;font-display:block;src:url(/assets/fonts/FeatureDisplay-Extralight.woff2) format("woff2") }
@font-face { font-family:Feature Display;font-weight:400;font-style:normal;font-display:block;src:url(/assets/fonts/FeatureDisplay-Regular.woff2) format("woff2") }
@font-face { font-family:Britti Sans;font-weight:400;font-style:normal;font-display:block;src:url(/assets/fonts/BrittiSans-Regular.woff2) format("woff2") }
@font-face { font-family:Britti Sans;font-weight:300;font-style:normal;font-display:block;src:url(/assets/fonts/BrittiSans-Light.woff2) format("woff2") }
@font-face { font-family:Britti Sans;font-weight:600;font-style:normal;font-display:block;src:url(/assets/fonts/BrittiSans-Semibold.woff2) format("woff2") }
html { width:100%;height:100%;color:var(--color-white);line-height:1.4 }
body { position:fixed;width:100%;height:100%;overflow:hidden;margin:0;overscroll-behavior:none;touch-action:none }
* { box-sizing:border-box }
section { position:relative;width:100% }
#home-everblade { padding-bottom:calc(var(--vh) * 500) }
#home-everblade .section__content { height:calc(var(--vh) * 100) }
#home-everblade .title-wrapper { position:relative;display:flex }
#home-everblade .title { z-index:2;line-height:.8 }
#home-everblade .title>span { display:inline-block;transform:translate(.4ex);overflow:hidden }
#home-everblade .title>span:nth-child(1) span { padding-right:.25em;display:block;transform:translateY(.15ex) }
#home-everblade .title>span:nth-child(2) span { padding-left:.25em;display:block;transform:translateY(.15ex) }
#home-everblade .subtitle { display:flex;flex-flow:row wrap;align-items:center;justify-content:center;max-width:20ch;position:absolute;bottom:0;left:50%;transform:translate(-50%,50%) }
#home-everblade .subtitle span { text-align:center;z-index:1;transform:translateY(.5ex) }
#home-everblade #home-everblade__logo { --width: calc(1.75 * var(--h1));--opacity: 1;position:absolute;height:var(--width);width:var(--width);top:50%;left:50%;transform:translate(-50%,-50%);z-index:-1 }
#home-everblade #home-everblade__logo div { position:relative;height:0;width:var(--width);padding-bottom:var(--width) }
#home-everblade #home-everblade__logo div:before { content:"";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-45deg);width:65%;height:65%;backdrop-filter:blur(calc(.15em * var(--opacity)));background:rgba(255,255,255,calc(.03 * var(--opacity)));z-index:-2 }
#home-everblade .description { position:absolute;left:50%;bottom:var(--site-padding-y);transform:translate(-50%);max-width:50ch;text-align:center;padding-top:2rem }
#home-everblade__logo-canvas { position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:100%;aspect-ratio:1/1 }
.section { position:relative }
.section__content { position:relative;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:var(--site-padding-y) var(--site-padding-x) }
.title-wrapper { width:100%;display:flex;flex-direction:column;align-items:flex-start;gap:1em;justify-content:center;align-items:center }
.title { text-shadow:0 0 .12em rgba(0,0,0,.3) }
.subtitle, .description { text-shadow:0 0 1em rgba(0,0,0,.3) }
@media (max-width: 991.98px) {
#home-everblade .title { display:flex;position:relative;left:auto;bottom:auto }
#home-everblade .title>span { padding-bottom:2rem }
#home-everblade .title span:nth-child(1) { display:block;transform:none;position:relative }
#home-everblade .title span:nth-child(1) span { padding-right:0 }
#home-everblade .title span:nth-child(2) { display:block;transform:none;position:relative;margin-left:.4ex }
#home-everblade .title span:nth-child(2) span { padding-left:0 }
#home-everblade .subtitle { flex-direction:column;font-size:1.25rem }
#home-everblade .subtitle span { transform:translateY(.25ex) }
#home-everblade .subtitle span:nth-child(3) { display:none }
#home-everblade #home-everblade__logo { --width: min(30vh, 90vw) }
#home-everblade .description { position:relative;left:auto;bottom:auto;transform:none;margin:0 auto }
}
